async function scanImageHeaders(file){let u=new Uint8Array(await file.slice(0,Math.min(file.size,2097152)).arrayBuffer()),exif=false,dpi=null,header='';if(u.length>=8&&u[0]===137&&u[1]===80&&u[2]===78&&u[3]===71){header='PNG';for(let p=8;p+8<=u.length;){let len=((u[p]<<24)>>>0)|(u[p+1]<<16)|(u[p+2]<<8)|u[p+3],type=String.fromCharCode(u[p+4],u[p+5],u[p+6],u[p+7]);if(type==='pHYs'&&len>=9&&p+8+len<=u.length&&u[p+8+8]===1){let x=(((u[p+8]<<24)>>>0)+(u[p+9]<<16)+(u[p+10]<<8)+u[p+11])>>>0;let y=(((u[p+12]<<24)>>>0)+(u[p+13]<<16)+(u[p+14]<<8)+u[p+15])>>>0;if(x&&y)dpi=Math.round(((x+y)/2)*0.0254)}p+=12+len}}else if(u[0]===255&&u[1]===216){header='JPEG';let p=2;while(p+9<u.length){if(u[p]!==255){p++;continue}let marker=u[p+1];if(marker===217||marker===218)break;let len=(u[p+2]<<8)|u[p+3];if(len<2||p+2+len>u.length)break;if(marker===225&&len>=8&&String.fromCharCode(...u.slice(p+4,p+10))==='Exif\0\0')exif=true;if(marker===224&&len>=16&&String.fromCharCode(...u.slice(p+4,p+10))==='JFIF\0'){let units=u[p+12],x=(u[p+13]<<8)|u[p+14],y=(u[p+15]<<8)|u[p+16];if(units===1)dpi=Math.round((x+y)/2);else if(units===2)dpi=Math.round(((x+y)/2)*2.54)}p+=2+len}}return{exif,dpi,header}}
