if(t==='batchResize')return '<div class=control><label>Width</label><input id=bw type=number value=1200 min=1></div><div class=control><label>Output</label><select id=fmt><option value=image/jpeg>JPG</option><option value=image/png>PNG</option><option value=image/webp>WebP</option></select></div>';
