async function decodeBase64(){let raw=$('#in').value.trim();if(!raw){status('Paste a Base64 or Data URI first.');return}try{let data=raw.indexOf('data:')===0?raw:'data:image/png;base64,'+raw;let im=await new Promise((ok,bad)=>{let i=new Image();i.onload=()=>ok(i);i.onerror=bad;i.src=data});if(!withinPixels(im.width,im.height)){status('That image is too large for safe browser processing.');return}let c=can(im.width,im.height);c.getContext('2d').drawImage(im,0,0);finish(c,await blob(c,'image/png',1),'decoded.png');status('Decoded successfully.')}catch(e){status('The Base64 or Data URI could not be decoded.')}}
function finish(c,b,n){if(!b){state.blob=null;let d=$('#download');if(d)d.disabled=true;status('Could not create an output file in this browser.');return}state.blob=b;state.name=n;preview(c);$('#download').disabled=false;$('#meta').innerHTML='<div><small>Output</small><b>'+esc(n)+'</b></div><div><small>Size</small><b>'+fmt(b.size)+'</b></div><div><small>Dimensions</small><b>'+c.width+' × '+c.height+'</b></div>';let delta=state.file&&state.file.size?Math.round((1-b.size/state.file.size)*100):0;status('Done · '+fmt(b.size)+(delta>0?' · '+delta+'% smaller':delta<0?' · '+Math.abs(delta)+'% larger':''))}
async function inspect(){let i=state.img,f=state.file,g=(a,b)=>{while(b){let t=a%b;a=b;b=t}return a},d=g(i.width,i.height),rows=[['File',esc(f.name)],['Type',esc(f.type||'unknown')],['File size',fmt(f.size)],['Dimensions',i.width+' × '+i.height],['Megapixels',(i.width*i.height/1e6).toFixed(2)],['Aspect ratio',(i.width/d)+':'+(i.height/d)]];let scan=await scanImageHeaders(f);if(T.type==='dpi')rows.push(['Embedded resolution',scan.dpi?scan.dpi+' DPI':'Not found in common headers']);if(T.type==='metadata')rows.push(['EXIF metadata',scan.exif?'Detected':'Not detected']);rows.push(['Image header',scan.header||'Standard browser-readable image']);$('#extra').innerHTML='<div class=result-list>'+rows.map(r=>'<div class=result-row><span>'+r[0]+'</span><b>'+r[1]+'</b></div>').join('')+'</div>';status('Inspection complete.')}
function dominant(){let s=Number($('#samples').value),ratio=state.img.width/state.img.height,w=s,h=Math.max(1,Math.round(s/ratio));if(ratio<1){h=s;w=Math.max(1,Math.round(s*ratio))}let o=can(w,h),c=o.getContext('2d');c.drawImage(state.img,0,0,w,h);let d=c.getImageData(0,0,w,h).data,map={};for(let i=0;i<d.length;i+=4){let r=Math.min(255,Math.round(d[i]/32)*32),g=Math.min(255,Math.round(d[i+1]/32)*32),b=Math.min(255,Math.round(d[i+2]/32)*32),k=r+','+g+','+b;map[k]=(map[k]||0)+1}let top=Object.keys(map).sort((a,b)=>map[b]-map[a]).slice(0,6);$('#extra').innerHTML='<div class=result-list>'+top.map(k=>{let p=k.split(','),h='#'+p.map(v=>Number(v).toString(16).padStart(2,'0')).join('');return '<div class=result-row><span>'+h+'</span><span style="width:34px;height:18px;background:'+h+';border:1px solid #888"></span></div>'}).join('')+'</div>';status('Dominant colors calculated.')}
async function compare(){if(!state.img||!state.second){status('Choose both images first.');return}let b=await load(state.second);if(!withinPixels(b.width,b.height)){status('The second image is too large for safe browser comparison.');return}let box=$('#preview');box.innerHTML='<div class=compare-grid><div><div class=tool-type>IMAGE A</div><canvas id=a></canvas></div><div><div class=tool-type>IMAGE B</div><canvas id=b></canvas></div></div>';let ca=$('#a'),cb=$('#b');ca.width=state.img.width;ca.height=state.img.height;ca.getContext('2d').drawImage(state.img,0,0);cb.width=b.width;cb.height=b.height;cb.getContext('2d').drawImage(b,0,0);$('#extra').innerHTML='<div class=result-list><div class=result-row><span>A</span><b>'+state.img.width+' × '+state.img.height+' · '+fmt(state.file.size)+'</b></div><div class=result-row><span>B</span><b>'+b.width+' × '+b.height+' · '+fmt(state.second.size)+'</b></div></div>';status('Comparison ready.')}
async function batch(){if(!state.files.length){status('Choose multiple images first.');return}let out=[],failed=[],m=$('#fmt').value;for(let i=0;i<state.files.length;i++){status('Processing '+(i+1)+' / '+state.files.length);let f=state.files[i];try{let im=await load(f);if(im.width*im.height>MAX_PIXELS){failed.push(f.name);continue}let c;if(T.type==='batchCompress'){c=can(im.width,im.height);c.getContext('2d').drawImage(im,0,0);out.push([outName(f,m),await blob(c,m,Number($('#q').value)/100)])}else{let w=Number($('#bw').value)||1200,h=im.height*w/im.width;if(!withinPixels(w,h)){failed.push(f.name);continue}c=can(w,h);c.getContext('2d').drawImage(im,0,0,w,h);out.push([outName(f,m),await blob(c,m,.94)])}}catch(e){failed.push(f.name)}}$('#extra').innerHTML='<div class=result-list>'+out.map((r,i)=>'<div class=result-row><span>'+esc(r[0])+' · '+fmt(r[1].size)+'</span><button class=btn data-i='+i+'>Download</button></div>').join('')+'</div>'+(failed.length?'<div class=status>Skipped: '+failed.length+' file(s) could not be processed.</div>':'');out.forEach((r,i)=>$('#extra').querySelector('[data-i="'+i+'"]').onclick=()=>dl(r[1],r[0]));status(out.length+' results ready.'+(failed.length?' '+failed.length+' skipped.':''))}
